from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def constructMaximumBinaryTree(self, nums: List[int]) -> Optional[TreeNode]:
        stack = []
        for x in nums:
            curr = TreeNode(x)
            while stack and stack[-1].val < x:
                curr.left = stack.pop()
            if stack:
                stack[-1].right = curr
            stack.append(curr)
        return stack[0] if stack else None

class Solution {
public:
    TreeNode* constructMaximumBinaryTree(vector<int>& nums) {
        vector<TreeNode*> stk;
        for (int x : nums) {
            TreeNode* curr = new TreeNode(x);
            while (!stk.empty() && stk.back()->val < x) {
                curr->left = stk.back();
                stk.pop_back();
            }
            if (!stk.empty()) {
                stk.back()->right = curr;
            }
            stk.push_back(curr);
        }
        return stk.empty() ? nullptr : stk.front();
    }
};

class Solution {
    public TreeNode constructMaximumBinaryTree(int[] nums) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        for (int x : nums) {
            TreeNode curr = new TreeNode(x);
            while (!stack.isEmpty() && stack.peek().val < x) {
                curr.left = stack.pop();
            }
            if (!stack.isEmpty()) {
                stack.peek().right = curr;
            }
            stack.push(curr);
        }
        return stack.isEmpty() ? null : stack.peekLast();
    }
}

var constructMaximumBinaryTree = function(nums) {
    const stack = [];
    for (const x of nums) {
        const curr = new TreeNode(x);
        while (stack.length > 0 && stack[stack.length - 1].val < x) {
            curr.left = stack.pop();
        }
        if (stack.length > 0) {
            stack[stack.length - 1].right = curr;
        }
        stack.push(curr);
    }
    return stack.length > 0 ? stack[0] : null;
};
